function splitOddAndEven(n) {
    const str = n.toString();
    const result = [];
    let current = str[0];

    for (let i = 1; i < str.length; i++) {
        const prevIsOdd = (parseInt(str[i - 1]) % 2) === 1;
        const currIsOdd = (parseInt(str[i]) % 2) === 1;

        if (prevIsOdd === currIsOdd) {
            current += str[i];
        } else {
            result.push(parseInt(current));
            current = str[i];
        }
    }
    result.push(parseInt(current));

    return result;
}

